UPDATE tasks
SET research_trends = jsonb_build_array(
    '**Detection accuracy is moving into general-purpose vision encoders.** The strongest [COCO val2017](/benchmark/coco-val2017?task=object-detection) systems increasingly attach simple detector adapters to scaled pretrained features: [DINOv3](/paper/2508.10104) with Plain-DETR leads the table, [Perception Encoder](/paper/2504.13181) with DETA nearly matches it, and [DEIMv2](/paper/2509.20787) distills DINOv3 into models spanning server to mobile. Key themes are self-supervision, vision-language pretraining, spatial alignment, frozen or distilled backbones, and lightweight adaptation.',
    '**Closed label sets are giving way to promptable, language-aware detection.** [Grounding DINO](/paper/2303.05499) made category names and referring expressions detector inputs; [SAM 3](/paper/2511.16719) now combines text and image exemplars for concept detection, segmentation, and tracking, while [Rex-Omni](/paper/2510.12798) predicts quantized coordinates as language tokens. The [ODinW13](/benchmark/odinw13-subset-of-odinw?task=object-detection) and [LVIS](/benchmark/lvis-object-detection?task=object-detection) results show the shift toward open-vocabulary, zero/few-shot transfer, multimodal prompting, and autoregressive localization.',
    '**Real-time detection is becoming end-to-end and NMS-free.** Building on [DETR](/paper/2005.12872) and direct set prediction, [D-FINE](/paper/2410.13842) improves localization with distribution refinement and self-distillation, [RF-DETR](/paper/2511.09554) searches accuracy-latency Pareto points for each deployment target, and [YOLO26](/paper/2606.03748) adopts native NMS-free inference across model scales. The recurring frontier is lightweight decoders, better query and localization training, hardware-aware scaling, and less hand-designed post-processing.'
),
updated_at = NOW()
WHERE slug = 'object-detection';
